_INT64_MIN = -(1 << 63)
_INT64_MAX = (1 << 63) - 1


def _check_checkpoint_leaf(value):
    """Reject values the checkpoint format cannot represent losslessly."""
    if isinstance(value, bool):
        raise ValueError("checkpoint state must not contain booleans")
    if isinstance(value, int):
        if not _INT64_MIN <= value <= _INT64_MAX:
            raise ValueError("checkpoint state contains an out-of-range integer")
    elif isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("checkpoint state contains a non-finite float")
    else:
        raise ValueError(
            f"checkpoint state must contain numbers only, got {type(value).__name__}"
        )


def _check_checkpoint_tree(value):
    if isinstance(value, list):
        for item in value:
            _check_checkpoint_tree(item)
    else:
        _check_checkpoint_leaf(value)


def _in_place_update(data, grad_data, lr):
    """Apply ``data <- data - lr * grad_data`` to nested lists in place."""
    if isinstance(data, list):
        for index, item in enumerate(data):
            if isinstance(item, list):
                _in_place_update(item, grad_data[index], lr)
            else:
                data[index] = item - lr * grad_data[index]
    else:
        # Scalar tensors cannot be mutated through their holder; the caller
        # (_replace_data) handles the scalar case directly.
        raise TypeError("scalar tensors are updated via _replace_data")


